&lt;/div&gt;</description><pubDate>Wed, 12 Aug 2026 15:45:02 +0000</pubDate><guid>https://www.mozilla.org/en-US/careers/position/gh/7947405/</guid><category>Remote Canada</category><category>Firefox</category><category>New Products</category><category>Firefox</category><category>Core Services</category><category>Infrastructure</category><category>Mozilla.org</category><category>New Products</category><category>Firefox</category><category>Marketing</category><category>MZLA/Thunderbird</category><category>Firefox</category><category>Firefox</category><category>Firefox</category><category>Core Services</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Marketing</category><category>New Products</category><category>New Products</category><category>New Products</category><category>Firefox</category><category>Firefox</category><category>Ads</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>People</category><category>People</category><category>Firefox</category><category>New Products</category><category>Firefox</category><category>Core Services</category><category>Infrastructure</category><category>Mozilla.org</category><category>New Products</category><category>Firefox</category><category>Marketing</category><category>MZLA/Thunderbird</category><category>Firefox</category><category>Firefox</category><category>Firefox</category><category>Core Services</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Marketing</category><category>New Products</category><category>New Products</category><category>New Products</category><category>Firefox</category><category>Firefox</category><category>Ads</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Infrastructure</category><category>