tegory>Firefox</category><category>Firefox</category><category>Firefox</category><category>Core Services</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Marketing</category><category>New Products</category><category>New Products</category><category>New Products</category><category>Firefox</category><category>Firefox</category><category>Ads</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>People</category><category>People</category><category>Firefox</category><category>New Products</category><category>Firefox</category><category>Core Services</category><category>Infrastructure</category><category>Mozilla.org</category><category>New Products</category><category>Firefox</category><category>Marketing</category><category>MZLA/Thunderbird</category><category>Firefox</category><category>Firefox</category><category>Firefox</category><category>Core Services</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Marketing</category><category>New Products</category><category>New Products</category><category>New Products</category><category>Firefox</category><category>Firefox</category><category>Ads</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>People</category><category>People</category><category>Firefox</category><category>New Products</category><category>Firefox</category><category>Core Services</category><category>Infrastructure</category><category>Mozilla.org</category><category>New Products</category><category>Firefox</category><category>Marketing</category><category>MZLA/Thunderbird</category><category>Firefox</category><category>Firefox</category><category>Firefox</category><category>Core Services</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Marketing</category><category>New Products</category><category>New Products</category><category>New Products</category><category>Firefox</category><category>Firefox</category><category>Ads</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>People</category><category>People</category><category>Firefox</category><category>New Products</category><category>Firefox</category><category>Core Services</category><category>Infrastructure</category><category>Mozilla.org</category><category>New Products</category><category>Firefox</category><category>Marketing</category><category>MZLA/Thunderbird</category><category>Firefox</category><category>Firefox</category><category>Firefox</category><category>Core Services</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Marketing</category><category>New Products</category><category>New Products</category><category>New Products</category><category>Firefox</category><category>Firefox</category><category>Ads</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>People</category><category>People</category><category>Firefox</category><category>New Products</category><category>Firefox</category><category>Core Services</category><category>Infrastructure</category><category>Mozilla.org</category><category>New Products</category><category>Firefox</category><category>Marketing</category></item><item><title>Technical Content Marketing Specialist</title><link>https://www.mozilla.org/en-US/careers/position/gh/7983283/</link><description>&lt;p&gt;&lt;strong&gt;Why Thunderbird?&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;Thunderbird is one of the world’s most trusted open-source email applications, empowering more than 20 million people globally. At MZLA, the team behind Thunderbird, we build privacy-respecting communication tools that help people manage their digital lives while staying in control of their data.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;We are open source by design. Our products are developed transparently and in collaboration with a global community of contributors, and that same spirit shapes how we work: collaboratively, inclusively, and with a shared commitment to putting users first.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;Our small but growing distributed team includes 65+ people across seven countries. As Thunderbird evolves beyond a single desktop application, we are expanding across desktop, mobile, and paid services to build independent, privacy-respecting alternatives to big tech ecosystems.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;Our revenue model combines user donations, which help keep Thunderbird’s apps freely available, with paid services that cover the costs of hosted offerings while supporting long-term sustainability and continued innovation.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;A note about MZLA and Mozilla:&lt;/strong&gt;&lt;span&gt; &lt;/span&gt;&lt;span&gt;MZLA Technologies Corporation is the nonprofit-owned company behind Thunderbird and part of the Mozilla family. MZLA is separate from Mozilla Corporation and has its own compensation programs, benefits, and employment policies.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;To learn more, visit &lt;/span&gt;&lt;a href="http://www.thunderbird.net"&gt;&lt;span&gt;www.thunderbird.net&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;The opportunity&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;As the Technical Content Marketing Specialist at MZLA, you'll help tell the story of Thunderbird's growing ecosystem of desktop, mobile, and web-based communication products. Working closely with the Marketing Manager and cross-functional partners across Product, Engineering, Design, and Community teams, you'll create and execute marketing programs that drive product awareness, user engagement, adoption, and retention.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;This is a hands-on role for someone who enjoys translating technology into compelling, user-focused stories and content. You'll create and publish content that helps users discover, understand, and get value from Thunderbird's products and services, while supporting launches, feature announcements, user education, and broader brand initiatives.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What you’ll do &lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span&gt;Execute day-to-day social media activities, including content scheduling, publishing, monitoring, engagement, and reporting.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Draft and publish blog posts, product announcements, release communications, marketing emails, newsletters, user education content, and other digital content that helps users understand and adopt Thunderbird products and services.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Support product launches, feature announcements, adoption campaigns, and promotional activities across multiple digital channels.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Monitor social media engagement, coordinating with internal teams when additional context or support is needed.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Maintain editorial and campaign calendars to ensure timely delivery of marketing activities.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Track and report on performance metrics, identifying trends and optimization opportunities.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Support email marketing and automation activities, including list management, campaign setup, and workflow maintenance.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Assist with customer surveys and feedback collection to inform marketing and product insights.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Coordinate with internal teams and external vendors to support campaign execution and content development.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Ensure marketing materials align with brand standards and messaging guidelines.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Support ad hoc marketing and communications projects as needed.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What you bring &lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span&gt;3+ years of experience in marketing, communications, digital content, or a related role.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Experience marketing software, SaaS, technology products, developer tools, consumer applications, or other digital products to a global audience.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Demonstrated experience executing social media, email, and digital marketing activities across multiple channels.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Strong writing, copyediting, and proofreading skills with the ability to adapt messaging for different audiences and platforms.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Experience with social media management tools, email marketing platforms, content management systems, and digital marketing technologies.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Strong organizational skills and attention to detail, with the ability to manage multiple priorities and deadlines.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Ability to collaborate effectively across cross-functional teams in a distributed, asynchronous environment.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Proactive mindset with the ability to take ownership of work and follow projects through to completion.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Familiarity with marketing analytics and reporting tools.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Excellent verbal and written communication skills.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Ability to learn and responsibly use emerging technologies, including AI-enabled tools, to improve workflows.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Ability to support a global organization with understanding of different cultural dynamics and practices.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Bonus points for&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span&gt;Familiarity with open-source communities or privacy-focused technology products.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Experience with survey and customer feedback platforms.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Basic experience using graphic design tools such as Canva or Adobe Creative Suite.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Familiarity with SEO and digital content optimization best practices.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What success looks like&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;You'll be successful in this role if you're equally comfortable learning about technical products, collaborating with product and engineering teams, and creating high-quality content that helps users understand why Thunderbird matters.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Work environment&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;This is a full-time, fully remote position. You’ll join a distributed team of Thunderbird staff, open-source community members, and contributors from around the world.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;We rely on clear communication, thoughtful documentation, and collaborative decision-making to work effectively across time zones and disciplines.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;You'll be part of the marketing team, working closely with product, engineering, and community colleagues in a collaborative, fast-paced environment. &lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Compensation &amp;amp; benefits&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;We benchmark our base salaries to local markets and target the 60th percentile of the peer market. The salary ranges for this role are:&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span&gt;US: $72,000 - $86,000 USD&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Canada: $72,000 - $82,000 CAD&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span&gt;We may consider candidates with strong skills but less than the required experience. Title, level and compensation will be determined based on qualifications and experience.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;In addition to competitive salaries, we offer a comprehensive benefits package designed to support your whole self.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Work &amp;amp; career&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span&gt;Fully remote work &amp;amp; schedule flexibility&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Company-provided laptop&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Annual bonus program&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Monthly remote work stipend&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Annual professional development stipend&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Industry conferences&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Company all-hands and team gatherings&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Rest &amp;amp; play&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span&gt;24 days PTO per year (prorated) &lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Your birthday&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Year-end company shutdown&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;9 wellbeing days &lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Public holidays&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Other paid leave&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Quarterly wellbeing stipend for personal / family activities&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Health &amp;amp; family&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span&gt;401(k) / RRSP&lt;/span&gt;&lt;span&gt; contributions&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Health, dental, &amp;amp; vision insurance&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Disability insurance&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Life insurance&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Employee assistance program &lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Paid parental leave&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Paid sick days &lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Work eligibility&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;Applicants must reside in and &lt;/span&gt;&lt;strong&gt;have permanent work authorization&lt;/strong&gt;&lt;span&gt; for the country location(s) specified in the posting. We are unable to consider applicants outside of these markets at this time. And, we do not provide visa sponsorship.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;How to apply&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;Please apply directly through our &lt;/span&gt;&lt;a href="https://www.mozilla.org/en-US/careers/listings/?team=MZLA/Thunderbird"&gt;&lt;span&gt;career page&lt;/span&gt;&lt;/a&gt;&lt;span&gt;. We carefully review every cover letter and screening question, so take the time to answer each fully.&lt;/span&gt;&lt;strong&gt; &lt;/strong&gt;&lt;span&gt;We value authentic, thoughtful responses that reflect your own experience and perspective. It is fine to use AI tools to polish your writing, but your answers should be your own. &lt;/span&gt;&lt;strong&gt;Candidates who submit generic or unoriginal AI-generated responses may be disqualified from further consideration.&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Our commitment to diversity, equity, and inclusion&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;MZLA believes in the value of diverse creative practices and forms of knowledge, and knows diversity, equity and inclusion are crucial to and enrich the company’s core mission. We encourage applications from everyone, including members of all equity-seeking communities, such as (but not limited to) women, racialized and Indigenous persons, persons with disabilities, persons of all sexual orientations, gender identities and expressions.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;We are an equal opportunity employer. We do not discriminate on the basis of race (including hairstyle and texture), religion (including religious grooming and dress practices), gender, gender identity, gender expression, color, national origin, pregnancy, ancestry, domestic partner status, disability, sexual orientation, age, genetic predisposition, medical condition, marital status, citizenship status, military or veteran status, or any other basis covered by applicable laws. MZLA will not tolerate discrimination or harassment based on any of these characteristics or any other unlawful behavior, conduct, or purpose. &lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;We will ensure that qualified individuals with disabilities are provided reasonable accommodations to participate in the job application or interview process, to perform essential job functions, and to receive other benefits and privileges of employment, as appropriate. Please contact us at&lt;/span&gt;&lt;strong&gt; &lt;/strong&gt;&lt;strong&gt;hiringaccommodations@thunderbird.net&lt;/strong&gt;&lt;span&gt; to request accommodation.&lt;/span&gt;&lt;/p&gt;</description><pubDate>Mon, 27 Jul 2026 18:33:42 +0000</pubDate><guid>https://www.mozilla.org/en-US/careers/position/gh/7983283/</guid><category>Remote Canada</category><category>Firefox</category><category>New Products</category><category>Firefox</category><category>Core Services</category><category>Infrastructure</category><category>Mozilla.org</category><category>New Products</category><category>Firefox</category><category>Marketing</category><category>MZLA/Thunderbird</category><category>Firefox</category><category>Firefox</category><category>Firefox</category><category>Core Services</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Marketing</category><category>New Products</category><category>New Products</category><category>New Products</category><category>Firefox</category><category>Firefox</category><category>Ads</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>People</category><category>People</category><category>Firefox</category><category>New Products</category><category>Firefox</category><category>Core Services</category><category>Infrastructure</category><category>Mozilla.org</category><category>New Products</category><category>Firefox</category><category>Marketing</category><category>MZLA/Thunderbird</category><category>Firefox</category><category>Firefox</category><category>Firefox</categor