MZLA/Thunderbird</category><category>People</category><category>People</category><category>Firefox</category><category>New Products</category><category>Firefox</category><category>Core Services</category><category>Infrastructure</category><category>Mozilla.org</category><category>New Products</category><category>Firefox</category><category>Marketing</category><category>MZLA/Thunderbird</category><category>Firefox</category><category>Firefox</category><category>Firefox</category><category>Core Services</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Marketing</category><category>New Products</category><category>New Products</category><category>New Products</category><category>Firefox</category><category>Firefox</category><category>Ads</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>People</category><category>People</category><category>Firefox</category><category>New Products</category><category>Firefox</category><category>Core Services</category><category>Infrastructure</category><category>Mozilla.org</category><category>New Products</category><category>Firefox</category><category>Marketing</category><category>MZLA/Thunderbird</category><category>Firefox</category><category>Firefox</category><category>Firefox</category><category>Core Services</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Marketing</category><category>New Products</category><category>New Products</category><category>New Products</category><category>Firefox</category><category>Firefox</category><category>Ads</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>People</category><category>People</category><category>Firefox</category><category>New Products</category><category>Firefox</category><category>Core Services</category><category>Infrastructure</category><category>Mozilla.org</category><category>New Products</category><category>Firefox</category><category>Marketing</category><category>MZLA/Thunderbird</category><category>Firefox</category><category>Firefox</category><category>Firefox</category><category>Core Services</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Marketing</category><category>New Products</category><category>New Products</category><category>New Products</category><category>Firefox</category><category>Firefox</category><category>Ads</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>People</category><category>People</category><category>Firefox</category><category>New Products</category><category>Firefox</category><category>Core Services</category><category>Infrastructure</category><category>Mozilla.org</category><category>New Products</category><category>Firefox</category><category>Marketing</category><category>MZLA/Thunderbird</category><category>Firefox</category><category>Firefox</category><category>Firefox</category><category>Core Services</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Marketing</category><category>New Products</category><category>New Products</category><category>New Products</category><category>Firefox</category><category>Firefox</category><category>Ads</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>People</category><category>People</category><category>Firefox</category><category>New Products</category><category>Firefox</category><category>Core Services</category><category>Infrastructure</category><category>Mozilla.org</category><category>New Products</category><category>Firefox</category><category>Marketing</category><category>MZLA/Thunderbird</category><category>Firefox</category><category>Firefox</category><category>Firefox</category><category>Core Services</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Marketing</category><category>New Products</category><category>New Products</category><category>New Products</category><category>Firefox</category><category>Firefox</category><category>Ads</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Infrastructure</category><category>MZLA/Thunderbird</category><category>People</category><category>People</category><category>Firefox</category><category>New Products</category><category>Firefox</category><category>Core Services</category><category>Infrastructure</category><category>Mozilla.org</category><category>New Products</category><category>Firefox</category><category>Marketing</category><category>MZLA/Thunderbird</category><category>Firefox</category><category>Firefox</category><category>Firefox</category><category>Core Services</category><category>MZLA/Thunderbird</category><category>Infrastructure</category><category>Marketing</category><category>New Products</category><category>New Products</category><category>New Products</category><category>Firefox</category><category>Firefox</category></item><item><title>Engineering Manager, Ads</title><link>https://www.mozilla.org/en-US/careers/position/gh/8068415/</link><description>&lt;div&gt;
&lt;div&gt;To learn the Hiring Ranges for this position, please select your location from the &lt;strong&gt;Apply Now&lt;/strong&gt; dropdown menu.&lt;/div&gt;
&lt;p&gt;To learn more about our Hiring Range System, please click this &lt;a href="https://docs.google.com/document/d/1ylUe7Ou0EbsOtGRBtUv1sSld3lbZ4mrYzo59tEkSjY8/edit?usp=sharing"&gt;&lt;span&gt;&lt;strong&gt;link.&lt;/strong&gt;&lt;/span&gt;&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Why Mozilla?&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;Mozilla Corporation is the non-profit-backed technology company that has shaped the internet for the better over the last 25 years. We make pioneering brands like Firefox, the privacy-minded web browser. Now, with more than 225 million people around the world using our products each month, we’re shaping the next 25 years of technology and helping to reclaim an internet built for people, not companies. Our work focuses on diverse areas including AI, social media, security and more. And we’re doing this while never losing our focus on our core mission – to make the internet better for people. &lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;The Mozilla Corporation is wholly owned by the non-profit 501(c) Mozilla Foundation. This means we aren’t beholden to any shareholders — only to our mission. Along with thousands of volunteer contributors and collaborators all over the world, Mozillians design, build and distribute &lt;/span&gt;&lt;strong&gt;open-source&lt;/strong&gt;&lt;span&gt; software that enables people to enjoy the internet on their terms. &lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About this team and role:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;The Ads Engineering organization at Mozilla builds privacy-respecting advertising systems that support Mozilla’s products and business while aligning with our mission and values. Our teams focus on reliable, scalable systems that enable advertising experiences across Mozilla products.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;As an Engineering Manager on Ads Engineering, you will lead a team of software engineers working on Firefox Suggest Ads&lt;/span&gt;&lt;strong&gt;,&lt;/strong&gt;&lt;span&gt; the sponsored suggestion experiences within Firefox Suggest. This team builds and operates backend services, partner integrations, experimentation capabilities, and product-facing systems that help deliver relevant sponsored suggestions in Firefox while respecting user privacy and product quality expectations.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;You’ll be responsible for building a healthy, effective team; partnering closely with Product, Data, Privacy, Policy, Revenue, and Firefox engineering stakeholders; and ensuring your team delivers high-quality software in support of Ads Engineering goals.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span&gt;This role balances people leadership, execution, and collaboration, with a strong emphasis on mentoring engineers, navigating ambiguity, delivering results, and fostering a positive, inclusive team culture.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What you’ll do: &lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span&gt;Mentor, support, and develop a team of software engineers, helping them grow in impact and craft&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Lead your team through the delivery of Firefox Suggest Ads initiatives, including backend services, partner integrations, experimentation, measurement, reliability improvements, and product-facing integrations where requirements may evolve as privacy, policy, user experience, and business constraints become clearer&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Partner with product managers and cross-functional stakeholders to navigate ambiguity, particularly where user data, privacy expectations, or policy considerations shape technical and product decisions&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Ensure the software your team builds is reliable, maintainable, and aligned with Mozilla’s quality, security, and privacy standards&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Create an environment where engineers can do their best work, including healthy team processes, clear communication, and support through uncertainty&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Participate in hiring and onboarding to grow and strengthen the team over time&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What you’ll bring: &lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span&gt;6+ years of professional software engineering experience, including at least 2 years of people management experience&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;A track record of leading teams that successfully deliver production software&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Strong judgment around prioritization, execution, and balancing short-term delivery with long-term sustainability&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Familiarity with modern software development practices, including planning, issue triage, and delivery workflows&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Ability to collaborate effectively with product managers and partner teams to deliver outcomes&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Experience supporting engineers with varied skill sets, backgrounds, and levels of experience&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Comfort working in a distributed, asynchronous environment&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Experience in search, ads, recommendations, marketplaces, browser/client-platform integrations, or other privacy-sensitive product domains — or demonstrated ability to quickly learn complex domains where user trust, data practices, and business outcomes must be balanced&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Commitment to our values:&lt;/span&gt;&lt;/li&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span&gt;Welcoming differences&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Being relationship-minded&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Practicing responsible participation&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Having grit&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;What you’ll get:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span&gt;Generous performance-based bonus plans to all eligible employees - we share in our success as one team&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Rich medical, dental, and vision coverage&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Generous retirement contributions with 100% immediate vesting (regardless of whether you contribute)&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Quarterly all-company wellness days where everyone takes a pause together&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Country specific holidays plus a day off for your birthday&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;One-time home office stipend&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Annual professional development budget&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Quarterly well-being stipend&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Considerable paid parental leave&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Employee referral bonus program&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span&gt;Other benefits (life/AD&amp;amp;D, disability, EAP, etc. - varies by country)&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;About Mozilla &lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Mozilla exists to build the Internet as a public resource accessible to all because we believe that open and free is better than closed and controlled. When you work at Mozilla, you give yourself a chance to make a difference in the lives of Web users everywhere. And you give us a chance to make a difference in your life every single day. Join us to work on the Web as the platform and help create more opportunity and innovation for everyone online.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Commitment to diversity, equity, inclusion, and belonging&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Mozilla understands that valuing diverse creative practices and forms of knowledge are crucial to and enrich the company’s core mission.  We encourage applications from everyone, including members of all equity-seeking communities, such as (but certainly not limited to) women, racialized and Indigenous persons, persons with disabilities, persons of all sexual orientation&lt;span&gt;s, &lt;/span&gt;gender identities, and expressions.&lt;/p&gt;
&lt;p&gt;We will ensure that qualified individuals with disabilities are provided reasonable accommodations to participate in the job application or interview process, to perform essential job functions, and to receive other benefits and privileges of employment, as appropriate. Please contact us at &lt;a class="external-link" href="mailto:hiringaccommodation@mozilla.com"&gt;hiringaccommodation@mozilla.com&lt;/a&gt; to request accommodation.&lt;/p&gt;
&lt;p&gt;We are an equal opportunity employer. We do not discriminate on the basis of race (including hairstyle and texture), religion (including religious grooming and dress practices), gender, gender identity, gender expression, color, national origin, pregnancy, ancestry, domestic partner status, disability, sexual orientation, age, genetic predisposition, medical condition, marital status, citizenship status, military or veteran status, or any other basis covered by applicable laws.  Mozilla will not tolerate discrimination or harassment based on any of these characteristics or any other unlawful behavior, conduct, or purpose.&lt;/p&gt;
&lt;p&gt;Group: D&lt;/p&gt;
&lt;p&gt;#LI-DNI&lt;/p&gt;
